. (Join-Path $PSScriptRoot 'cloud-common.ps1')
$account='000000000000';$cluster='motorlog-cluster';$service='motorlog-backend-service';$taskFamily='motorlog-backend-task';$executionRole='motorlog-ecs-task-execution-role';$taskRole='motorlog-ecs-task-role';$dist=Join-Path $ProjectRoot 'dist';New-Item -ItemType Directory -Force -Path $dist|Out-Null
function Status([string]$Kind,[string]$Message){Write-Host (("[$Kind]").PadRight(10)+$Message)}
function Set-SecretValueFromFile([string]$Id,[string]$Value){$path=Join-Path ([IO.Path]::GetTempPath()) "motorlog-secret-$([guid]::NewGuid().ToString('N')).txt";try{[IO.File]::WriteAllText($path,$Value,(New-Object Text.UTF8Encoding($false)));Invoke-Aws secretsmanager create-secret --name $Id --secret-string "file://$($path.Replace('\','/'))"|ConvertFrom-Json}finally{if(Test-Path -LiteralPath $path){Remove-Item -LiteralPath $path -Force}}}
function Ensure-Secret([string]$Id,[scriptblock]$Factory,[switch]$Json){$check=Invoke-AwsExistenceCheck -Arguments @('secretsmanager','describe-secret','--secret-id',$Id) -NotFoundErrorCodes @('ResourceNotFoundException');if($check.Exists){if($Json){$value=(Invoke-Aws secretsmanager get-secret-value --secret-id $Id|ConvertFrom-Json).SecretString;try{$null=$value|ConvertFrom-Json -ErrorAction Stop}catch{throw "Existing secret $Id is not valid JSON; refusing to overwrite it."}};Status EXISTS "Secrets Manager $Id";return ($check.Output|ConvertFrom-Json).ARN};Status CREATE "Secrets Manager $Id";$created=Set-SecretValueFromFile $Id (&$Factory);if(-not $created.ARN){throw "Secret $Id creation verification failed."};(Invoke-Aws secretsmanager describe-secret --secret-id $Id|ConvertFrom-Json).ARN}
function Ensure-Role([string]$Name,[string]$Trust,[string]$Policy){$check=Invoke-AwsExistenceCheck -Arguments @('iam','get-role','--role-name',$Name) -NotFoundErrorCodes @('NoSuchEntity');if($check.Exists){$role=$check.Output|ConvertFrom-Json;Status EXISTS "IAM role $Name"}else{Status CREATE "IAM role $Name";$role=Invoke-Aws iam create-role --role-name $Name --assume-role-policy-document "file://$($Trust.Replace('\','/'))"|ConvertFrom-Json};$trustDocument=$role.Role.AssumeRolePolicyDocument;if($trustDocument -is [string]){$trustDocument=[Uri]::UnescapeDataString($trustDocument)|ConvertFrom-Json};if(@($trustDocument.Statement|Where-Object{$_.Principal.Service -eq 'ecs-tasks.amazonaws.com' -and @($_.Action)-contains 'sts:AssumeRole'}).Count -ne 1){throw "IAM role $Name does not trust ecs-tasks.amazonaws.com."};Invoke-Aws iam put-role-policy --role-name $Name --policy-name "$Name-policy" --policy-document "file://$($Policy.Replace('\','/'))"|Out-Null;Invoke-Aws iam get-role-policy --role-name $Name --policy-name "$Name-policy"|Out-Null;$role.Role}
function Container-Spec($Container){[ordered]@{name=[string]$Container.name;image=[string]$Container.image;essential=[bool]$Container.essential;portMappings=@($Container.portMappings|ForEach-Object{[ordered]@{containerPort=[int]$_.containerPort;protocol=[string]$_.protocol}});environment=@($Container.environment|ForEach-Object{[ordered]@{name=[string]$_.name;value=[string]$_.value}});secrets=@($Container.secrets|ForEach-Object{[ordered]@{name=[string]$_.name;valueFrom=[string]$_.valueFrom}});healthCheck=[ordered]@{command=@($Container.healthCheck.command);interval=[int]$Container.healthCheck.interval;timeout=[int]$Container.healthCheck.timeout;retries=[int]$Container.healthCheck.retries;startPeriod=[int]$Container.healthCheck.startPeriod};logConfiguration=[ordered]@{logDriver=[string]$Container.logConfiguration.logDriver;options=[ordered]@{'awslogs-group'=[string]$Container.logConfiguration.options.'awslogs-group';'awslogs-region'=[string]$Container.logConfiguration.options.'awslogs-region';'awslogs-stream-prefix'=[string]$Container.logConfiguration.options.'awslogs-stream-prefix'}}}}
function Task-Spec($Task){[ordered]@{family=[string]$Task.family;networkMode=[string]$Task.networkMode;requiresCompatibilities=@($Task.requiresCompatibilities);cpu=[string]$Task.cpu;memory=[string]$Task.memory;executionRoleArn=[string]$Task.executionRoleArn;taskRoleArn=[string]$Task.taskRoleArn;containerDefinitions=@($Task.containerDefinitions|ForEach-Object{Container-Spec $_})}}

Write-Host "`n===============================================`n       MOTORLOG ECS & CLOUD SERVICES`n===============================================`n"
$lbs=@((Invoke-Aws elbv2 describe-load-balancers --names motorlog-alb|ConvertFrom-Json).LoadBalancers);if($lbs.Count -ne 1){throw "Expected exactly one motorlog-alb, found $($lbs.Count)."};$alb=$lbs[0];Status EXISTS 'Motorlog ALB'
$vpcs=@((Invoke-Aws ec2 describe-vpcs|ConvertFrom-Json).Vpcs|Where-Object VpcId -eq $alb.VpcId);if($vpcs.Count -ne 1){throw "ALB VPC $($alb.VpcId) could not be uniquely discovered."};$vpc=$vpcs[0];Status OK "Existing ALB VPC discovered: $($vpc.VpcId)"
$subnetIds=@($alb.AvailabilityZones|ForEach-Object SubnetId|Where-Object{$_}|Select-Object -Unique);$allSubnets=@((Invoke-Aws ec2 describe-subnets|ConvertFrom-Json).Subnets);$subnets=@($allSubnets|Where-Object{$_.SubnetId -in $subnetIds -and $_.VpcId -eq $vpc.VpcId});if($subnets.Count -lt 2 -or @($subnets.AvailabilityZone|Select-Object -Unique).Count -lt 2){throw 'ALB subnets are not valid two-availability-zone ECS network inputs.'}
$groupIds=@($alb.SecurityGroups|Select-Object -Unique);$allGroups=@((Invoke-Aws ec2 describe-security-groups|ConvertFrom-Json).SecurityGroups);$groups=@($allGroups|Where-Object{$_.GroupId -in $groupIds -and $_.VpcId -eq $vpc.VpcId});if($groups.Count -ne $groupIds.Count -or -not $groups.Count){throw 'ALB security groups are missing or belong to an inconsistent VPC.'};Status OK 'ALB subnets and security groups verified'
$targetGroup=@((Invoke-Aws elbv2 describe-target-groups --names motorlog-http-targets|ConvertFrom-Json).TargetGroups);if($targetGroup.Count -ne 1 -or $targetGroup[0].VpcId -ne $vpc.VpcId){throw 'Existing Motorlog target group is missing or inconsistent.'};$hostTargets=@((Invoke-Aws elbv2 describe-target-health --target-group-arn $targetGroup[0].TargetGroupArn|ConvertFrom-Json).TargetHealthDescriptions);if(@($hostTargets|Where-Object{$_.Target.Port -in 3101,3102,3103}).Count -ne 3){throw 'The three existing ALB host targets are not intact.'};Status OK 'Existing ALB targets preserved; ECS service will remain independently addressable'

$appSecretArn=Ensure-Secret 'motorlog-app/config' {'{"environment":"local-floci","rateLimitMax":120,"rateLimitWindowMs":60000}'} -Json
$rateLimitSecretArn=Ensure-Secret 'motorlog-auth/rate-limit-key' { $b=New-Object byte[] 32;$g=[Security.Cryptography.RandomNumberGenerator]::Create();try{$g.GetBytes($b)}finally{$g.Dispose()};[Convert]::ToBase64String($b)}
$compose=Get-Content -LiteralPath (Join-Path $ProjectRoot 'infra\floci\docker-compose.yml') -Raw;if($compose -notmatch '(?ms)^\s*floci:.*?aliases:.*?-\s*floci\s*$'){throw 'The current Compose configuration does not provide the stable floci network alias.'};$flociContainer=if($compose-match'(?m)^\s*container_name:\s*([^\s#]+)'){$matches[1]}else{'motorlog-floci'}
$resolved=@(& docker exec $flociContainer getent hosts floci);if($LASTEXITCODE -ne 0 -or -not(($resolved-join' ') -match '\d+\.\d+\.\d+\.\d+')){throw 'The stable floci hostname is not resolvable in the current Docker environment.'};$flociEndpoint='http://floci:4566';Status OK "Stable Floci endpoint verified through $flociContainer"

$trustPath=Join-Path $dist 'ecs-trust.json';Write-JsonFile $trustPath @{Version='2012-10-17';Statement=@(@{Effect='Allow';Principal=@{Service='ecs-tasks.amazonaws.com'};Action='sts:AssumeRole'})}
$executionPolicy=Join-Path $dist 'ecs-execution-policy.json';Write-JsonFile $executionPolicy @{Version='2012-10-17';Statement=@(@{Effect='Allow';Action=@('logs:CreateLogStream','logs:PutLogEvents');Resource="arn:aws:logs:${Region}:${account}:log-group:/motorlog/ecs:*"},@{Effect='Allow';Action='secretsmanager:GetSecretValue';Resource=$rateLimitSecretArn})}
$taskPolicy=Join-Path $dist 'ecs-task-policy.json';Write-JsonFile $taskPolicy @{Version='2012-10-17';Statement=@(@{Effect='Allow';Action='events:PutEvents';Resource="arn:aws:events:${Region}:${account}:event-bus/motorlog-event-bus"},@{Effect='Allow';Action='sns:Publish';Resource="arn:aws:sns:${Region}:${account}:motorlog-notifications-topic"},@{Effect='Allow';Action='secretsmanager:GetSecretValue';Resource=$appSecretArn})}
$execution=Ensure-Role $executionRole $trustPath $executionPolicy;$taskRoleObject=Ensure-Role $taskRole $trustPath $taskPolicy;Status OK 'ECS IAM trust and permissions verified'
$logCheck=Invoke-AwsExistenceCheck -Arguments @('logs','describe-log-groups','--log-group-name-prefix','/motorlog/ecs') -NotFoundErrorCodes @('ResourceNotFoundException');$log=@(($logCheck.Output|ConvertFrom-Json).logGroups|Where-Object logGroupName -eq '/motorlog/ecs');if($log.Count){Status EXISTS 'CloudWatch log group /motorlog/ecs'}else{Status CREATE 'CloudWatch log group /motorlog/ecs';Invoke-Aws logs create-log-group --log-group-name /motorlog/ecs|Out-Null}

$image=if($env:MOTORLOG_ECS_IMAGE){$env:MOTORLOG_ECS_IMAGE}else{'motorlog-backend:scale-security'};& docker image inspect $image *> $null;if($LASTEXITCODE -ne 0){Status CREATE "Docker image $image";& docker build --tag $image $ProjectRoot;if($LASTEXITCODE -ne 0){throw "Docker image build failed for $image"}}else{Status EXISTS "Docker image $image"}
$desired=Task-Spec ([pscustomobject]@{family=$taskFamily;networkMode='awsvpc';requiresCompatibilities=@('FARGATE');cpu='256';memory='512';executionRoleArn=$execution.Arn;taskRoleArn=$taskRoleObject.Arn;containerDefinitions=@([pscustomobject]@{name='motorlog-backend';image=$image;essential=$true;portMappings=@([pscustomobject]@{containerPort=3000;protocol='tcp'});environment=@([pscustomobject]@{name='AWS_ENDPOINT_URL';value=$flociEndpoint},[pscustomobject]@{name='EVENT_BUS_NAME';value='motorlog-event-bus'},[pscustomobject]@{name='SNS_TOPIC_ARN';value="arn:aws:sns:${Region}:${account}:motorlog-notifications-topic"},[pscustomobject]@{name='APP_CONFIG_SECRET_NAME';value='motorlog-app/config'});secrets=@([pscustomobject]@{name='RATE_LIMIT_KEY_SECRET';valueFrom=$rateLimitSecretArn});healthCheck=[pscustomobject]@{command=@('CMD-SHELL','wget -qO- http://127.0.0.1:3000/api/health || exit 1');interval=30;timeout=5;retries=3;startPeriod=10};logConfiguration=[pscustomobject]@{logDriver='awslogs';options=[pscustomobject]@{'awslogs-group'='/motorlog/ecs';'awslogs-region'=$Region;'awslogs-stream-prefix'='backend'}}})})
$taskPath=Join-Path $dist 'ecs-task-definition.json';Write-JsonFile $taskPath $desired;$listed=Invoke-Aws ecs list-task-definitions --family-prefix $taskFamily --sort DESC|ConvertFrom-Json;$latestArn=@($listed.taskDefinitionArns|Select-Object -First 1);$taskDefinition=$null
if($latestArn){$current=(Invoke-Aws ecs describe-task-definition --task-definition $latestArn[0]|ConvertFrom-Json).taskDefinition;if(((Task-Spec $current)|ConvertTo-Json -Depth 20 -Compress) -eq ($desired|ConvertTo-Json -Depth 20 -Compress)){$taskDefinition=$current;Status EXISTS "ECS task definition $($current.taskDefinitionArn)"}}
if(-not $taskDefinition){Status CREATE 'ECS task definition revision';$taskDefinition=(Invoke-Aws ecs register-task-definition --cli-input-json "file://$($taskPath.Replace('\','/'))"|ConvertFrom-Json).taskDefinition}
$clusters=Invoke-Aws ecs list-clusters|ConvertFrom-Json;$clusterArn=@($clusters.clusterArns|Where-Object{$_ -match "/$([regex]::Escape($cluster))$"});if(-not $clusterArn){Status CREATE "ECS cluster $cluster";Invoke-Aws ecs create-cluster --cluster-name $cluster|Out-Null}else{Status EXISTS "ECS cluster $cluster"}
$network="awsvpcConfiguration={subnets=[$($subnets.SubnetId-join',')],securityGroups=[$($groups.GroupId-join',')],assignPublicIp=DISABLED}";$described=Invoke-Aws ecs describe-services --cluster $cluster --services $service|ConvertFrom-Json;$existing=@($described.services|Where-Object{$_.serviceName -eq $service -and $_.status -ne 'INACTIVE'}|Select-Object -First 1)
if($existing.Count){$ecsService=(Invoke-Aws ecs update-service --cluster $cluster --service $service --task-definition $taskDefinition.taskDefinitionArn --desired-count 1 --network-configuration $network|ConvertFrom-Json).service;Status EXISTS "ECS service $service"}else{Status CREATE "ECS service $service";$ecsService=(Invoke-Aws ecs create-service --cluster $cluster --service-name $service --task-definition $taskDefinition.taskDefinitionArn --desired-count 1 --launch-type FARGATE --network-configuration $network|ConvertFrom-Json).service}
$verifiedService=@((Invoke-Aws ecs describe-services --cluster $cluster --services $service|ConvertFrom-Json).services|Where-Object serviceName -eq $service);if($verifiedService.Count -ne 1 -or $verifiedService[0].status -ne 'ACTIVE' -or $verifiedService[0].desiredCount -ne 1){throw 'ECS service configuration verification failed.'};Status OK "ECS service configured; running tasks $($verifiedService[0].runningCount)/$($verifiedService[0].desiredCount) (configuration success is not workload health)"

$resourceId="service/$cluster/$service";Invoke-Aws application-autoscaling register-scalable-target --service-namespace ecs --resource-id $resourceId --scalable-dimension ecs:service:DesiredCount --min-capacity 1 --max-capacity 4|Out-Null
$scalingPath=Join-Path $dist 'ecs-scaling.json';Write-JsonFile $scalingPath @{TargetValue=50.0;PredefinedMetricSpecification=@{PredefinedMetricType='ECSServiceAverageCPUUtilization'};ScaleOutCooldown=60;ScaleInCooldown=60};Invoke-Aws application-autoscaling put-scaling-policy --policy-name motorlog-cpu-target-tracking --service-namespace ecs --resource-id $resourceId --scalable-dimension ecs:service:DesiredCount --policy-type TargetTrackingScaling --target-tracking-scaling-policy-configuration "file://$($scalingPath.Replace('\','/'))"|Out-Null
$scalable=@((Invoke-Aws application-autoscaling describe-scalable-targets --service-namespace ecs --resource-ids $resourceId|ConvertFrom-Json).ScalableTargets|Where-Object{$_.MinCapacity -eq 1 -and $_.MaxCapacity -eq 4});$policies=@((Invoke-Aws application-autoscaling describe-scaling-policies --service-namespace ecs --resource-id $resourceId|ConvertFrom-Json).ScalingPolicies|Where-Object{$_.PolicyName -eq 'motorlog-cpu-target-tracking' -and $_.TargetTrackingScalingPolicyConfiguration.TargetValue -eq 50});if(-not $scalable.Count -or -not $policies.Count){throw 'ECS auto scaling verification failed.'};Status OK 'Auto Scaling min=1 max=4 CPU target=50 verified'

$topic=(Invoke-Aws sns create-topic --name motorlog-notifications-topic|ConvertFrom-Json).TopicArn;if(-not $topic){throw 'SNS topic verification failed.'};Status OK 'SNS notification topic verified'
$busCheck=Invoke-AwsExistenceCheck -Arguments @('events','describe-event-bus','--name','motorlog-event-bus') -NotFoundErrorCodes @('ResourceNotFoundException');if($busCheck.Exists){Status EXISTS 'EventBridge bus motorlog-event-bus'}else{Status CREATE 'EventBridge bus motorlog-event-bus';Invoke-Aws events create-event-bus --name motorlog-event-bus|Out-Null};Invoke-Aws events describe-event-bus --name motorlog-event-bus|Out-Null
$patternPath=Join-Path $dist 'audit-event-pattern.json';Write-JsonFile $patternPath @{source=@('motorlog.application');'detail-type'=@('VehicleCreated','MaintenanceAdded','ReminderCompleted')};Invoke-Aws events put-rule --name motorlog-audit-rule --event-bus-name motorlog-event-bus --event-pattern "file://$($patternPath.Replace('\','/'))" --state ENABLED|Out-Null
$auditLogCheck=Invoke-AwsExistenceCheck -Arguments @('logs','describe-log-groups','--log-group-name-prefix','/motorlog/events/audit') -NotFoundErrorCodes @('ResourceNotFoundException');if(-not @(($auditLogCheck.Output|ConvertFrom-Json).logGroups|Where-Object logGroupName -eq '/motorlog/events/audit').Count){Invoke-Aws logs create-log-group --log-group-name /motorlog/events/audit|Out-Null}
$auditTrust=Join-Path $dist 'motorlog-audit-trust.json';Write-JsonFile $auditTrust @{Version='2012-10-17';Statement=@(@{Effect='Allow';Principal=@{Service='lambda.amazonaws.com'};Action='sts:AssumeRole'})};$auditPolicy=Join-Path $dist 'motorlog-audit-policy.json';Write-JsonFile $auditPolicy @{Version='2012-10-17';Statement=@(@{Effect='Allow';Action=@('logs:CreateLogStream','logs:PutLogEvents');Resource="arn:aws:logs:${Region}:${account}:log-group:/motorlog/events/audit:*"})}
$auditRoleName='motorlog-audit-runtime';$auditCheck=Invoke-AwsExistenceCheck -Arguments @('iam','get-role','--role-name',$auditRoleName) -NotFoundErrorCodes @('NoSuchEntity');if($auditCheck.Exists){$auditRole=$auditCheck.Output|ConvertFrom-Json}else{$auditRole=Invoke-Aws iam create-role --role-name $auditRoleName --assume-role-policy-document "file://$($auditTrust.Replace('\','/'))"|ConvertFrom-Json};Invoke-Aws iam put-role-policy --role-name $auditRoleName --policy-name motorlog-audit-least-privilege --policy-document "file://$($auditPolicy.Replace('\','/'))"|Out-Null
Push-Location $ProjectRoot;try{& node scripts/build-audit-logger.js;if($LASTEXITCODE -ne 0){throw 'Audit Lambda packaging failed'}}finally{Pop-Location};$auditFunction='motorlog-audit-logger';$auditZip=Join-Path $dist 'motorlog-audit-logger.zip';$auditEnvironment=Join-Path $dist 'motorlog-audit-environment.json';Write-JsonFile $auditEnvironment @{Variables=@{AWS_ENDPOINT_URL=$flociEndpoint;AUDIT_LOG_GROUP='/motorlog/events/audit';AUDIT_LOG_STREAM='motorlog-eventbridge-audit'}}
$auditFunctionCheck=Invoke-AwsExistenceCheck -Arguments @('lambda','get-function','--function-name',$auditFunction) -NotFoundErrorCodes @('ResourceNotFoundException');if($auditFunctionCheck.Exists){Invoke-Aws lambda update-function-code --function-name $auditFunction --zip-file "fileb://$($auditZip.Replace('\','/'))"|Out-Null;Wait-MotorlogLambdaActive -FunctionName $auditFunction|Out-Null;Invoke-Aws lambda update-function-configuration --function-name $auditFunction --runtime nodejs22.x --handler index.handler --role $auditRole.Role.Arn --timeout 15 --memory-size 256 --environment "file://$($auditEnvironment.Replace('\','/'))"|Out-Null}else{Invoke-Aws lambda create-function --function-name $auditFunction --runtime nodejs22.x --handler index.handler --role $auditRole.Role.Arn --zip-file "fileb://$($auditZip.Replace('\','/'))" --timeout 15 --memory-size 256 --environment "file://$($auditEnvironment.Replace('\','/'))"|Out-Null};Wait-MotorlogLambdaActive -FunctionName $auditFunction|Out-Null
$ruleArn="arn:aws:events:${Region}:${account}:rule/motorlog-event-bus/motorlog-audit-rule";$functionArn="arn:aws:lambda:${Region}:${account}:function:$auditFunction";$permissionCheck=Invoke-AwsExistenceCheck -Arguments @('lambda','get-policy','--function-name',$auditFunction) -NotFoundErrorCodes @('ResourceNotFoundException');$permissionExists=$false;if($permissionCheck.Exists){$p=(($permissionCheck.Output|ConvertFrom-Json).Policy|ConvertFrom-Json);$permissionExists=@($p.Statement|Where-Object Sid -eq 'motorlog-eventbridge-audit-invoke').Count -gt 0};if(-not $permissionExists){Invoke-Aws lambda add-permission --function-name $auditFunction --statement-id motorlog-eventbridge-audit-invoke --action lambda:InvokeFunction --principal events.amazonaws.com --source-arn $ruleArn|Out-Null}
$targets=@((Invoke-Aws events list-targets-by-rule --event-bus-name motorlog-event-bus --rule motorlog-audit-rule|ConvertFrom-Json).Targets);if(@($targets|Where-Object Id -eq 'motorlog-audit-logs').Count){Invoke-Aws events remove-targets --event-bus-name motorlog-event-bus --rule motorlog-audit-rule --ids motorlog-audit-logs|Out-Null};Invoke-Aws events put-targets --event-bus-name motorlog-event-bus --rule motorlog-audit-rule --targets "Id=motorlog-audit-lambda,Arn=$functionArn"|Out-Null;Status OK 'SNS and EventBridge audit resources verified'
Write-Host "`n-----------------------------------------------`nCloud services deployment: SUCCESS`n-----------------------------------------------"
